create or replace function api.insert_item(
    p_id uuid,
    p_title text,
    p_author text,
    p_shelf_code text,
    p_media text,
    p_actor_id uuid,
    p_actor_roles text[]
) returns setof public.items
language plpgsql
security definer
set search_path = public
as $$
declare
    v_row public.items;
begin
    -- この txn が触る行(ガードが読む親・実行者の行・これから書く行)を、表名のバイト順で全部掴んでから書く(交錯しても判定の前提が動かず、掴む順が 1 つなので詰まらない)。
    perform 1
    from public.items t
    where t.id = p_id
    for update of t;

    perform 1
    from public.patrons la
    where la.id = p_actor_id
    for share of la;

    -- 同じ id の行が既にあれば、挿入の前に再送の枝へ進む(行の before insert トリガは一意の衝突の判定より先に走るので、挿入まで進むと押し直しでも番号のずらし・上端の断り・確かめのトリガが動く)。上の掴みの後に見るので、同じ鍵の 1 回目がまだコミットしていなければここで待ってから見る。既にある行は上の掴みが掴んでいる(消す txn がまだコミットしていなければそこで待ち、消えていれば挿入へ進んで作り直しの断りに合流する)。
    if exists (select 1 from public.items where id = p_id) then
        if not (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian)) then
            raise exception using errcode = 'UC403', message = 'usecase_forbidden:item.create';
        end if;
        -- この表は再送で既存の行を返さない(resend.returns_existing: false)。同じ id の行があれば競合にする。
        raise exception using errcode = 'UC409', message = 'usecase_conflict:' || 'item.create', detail = 'resend_already_saved';
    end if;

    insert into public.items (
        id, title, author, shelf_code, media
    )
    select
        p_id,
        p_title,
        p_author,
        p_shelf_code,
        p_media
    where exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian)
    on conflict (id) do nothing
    returning * into v_row;

    -- 0 行の理由を分類する(ロール → 再送 → 状態 → ガード。作成に自分の状態の段は無い)。
    if not found then
        if not (exists (select 1 from public.patrons a where a.id = p_actor_id and a.is_librarian)) then
            raise exception using errcode = 'UC403', message = 'usecase_forbidden:item.create';
        end if;
        -- 0 行 = 同じ id で作成済み(冪等な再送)か、前提が崩れた(競合)。id の実在で見分ける。
        if exists (select 1 from public.items where id = p_id) then
            -- この表は再送で既存の行を返さない(resend.returns_existing: false)。同じ id の行があれば競合にする。
            raise exception using errcode = 'UC409', message = 'usecase_conflict:' || 'item.create', detail = 'resend_already_saved';
        end if;
        -- 照会は 3 つとも通った = 照会と書き込みの間に行が動いた(競合)。
        raise exception using errcode = 'UC409', message = 'usecase_conflict:item.create';
    end if;
    -- 同じ鍵の作成が監査ログに既にある = 1 回目の行が消された後の押し直し。作り直さずに断る(点検 23 回目 O23-2)。
    if exists (select 1 from public.domain_events r where r.entity_id = p_id and r.event_id = 'item.create') then
        if exists (select 1 from public.domain_events r where r.entity_id = p_id and r.event_id = 'item.create' and r.actor_id is not distinct from p_actor_id) then
            raise exception using errcode = 'UC412', message = 'usecase_guard:' || 'item.create', detail = 'resend_target_deleted';
        end if;
        raise exception using errcode = 'UC409', message = 'usecase_conflict:item.create';
    end if;

    insert into public.domain_events (event_id, entity, entity_id, actor_id, payload)
    values (
        'item.create', 'item', v_row.id, p_actor_id,
        jsonb_build_object(
            'title', p_title,
            'author', p_author,
            'shelf_code', p_shelf_code,
            'media', p_media
        )
    );

    return next v_row;
end;
$$;

comment on function api.insert_item(uuid, text, text, text, text, uuid, text[]) is
    '蔵書の作成(生成物)。冪等キーは引数の id。同じ id の行が既にあれば、再送でも既存の行を返さず UC409。by(ロール)とガードは本文が守る(RPC 単体で仕様どおり)。';

revoke all on function api.insert_item(uuid, text, text, text, text, uuid, text[]) from public;
grant execute on function api.insert_item(uuid, text, text, text, text, uuid, text[]) to service_role;
